"""Lead agent. The parent's ceiling is divided among the children it spawns."""

import asyncio

from .worker import run_subagent


async def research(question, budget_usd=4.0):
    plans = decompose(question)
    child_budget = budget_usd / max(len(plans), 1)
    findings = await asyncio.gather(
        *(run_subagent(p, budget_usd=child_budget) for p in plans)
    )
    return synthesise(question, findings)


def decompose(question):
    return ask_model_for_plans(question)
